def _autocorr(P, h):
    """A(h) = sum_j P_j P_{j+h} (exact)."""
    m = len(P)
    return sum(P[j] * P[j + h] for j in range(m - h))


def _window_sums(P, H):
    """sliding H-window sums W_t over the m + H - 1 positions
    t = -(H-1)..m-1 (zero padding outside; exact)."""
    m = len(P)
    out = []
    for t in range(-(H - 1), m):
        out.append(sum(P[j] for j in range(max(0, t),
                                           min(m, t + H))))
    return out


def _fejer_windowsum(P, H):
    """sum_{|h|<H} (1 - |h|/H) A(h) (exact Fractions)."""
    tot = _Fr(0)
    for h in range(-(H - 1), H):
        tot += (1 - _Fr(abs(h), H)) * _autocorr(P, abs(h))
    return tot


def _vdc_bound_sq(P, H, prefactor_m_only=False):
    """the vdC upper bound on |sum P|^2 (exact); the mutant flag
    replaces the correct prefactor (m + H - 1)/H by m/H."""
    m = len(P)
    pref = _Fr(m, H) if prefactor_m_only else _Fr(m + H - 1, H)
    return pref * _fejer_windowsum(P, H)


def _abel_bound(P, drop_terminal=False):
    """the F1 Abel/Erdos-Turan bound D* x V (exact); the mutant
    flag drops the terminal magnitude term of V."""
    m = len(P)
    sig = [1 if p > 0 else (-1 if p < 0 else 0) for p in P]
    a = [abs(p) for p in P]
    dstar = max(abs(sum(sig[:n + 1])) for n in range(m))
    var = sum(abs(a[j + 1] - a[j]) for j in range(m - 1))
    V = var if drop_terminal else (a[m - 1] + var)
    return dstar * V, dstar, V


