def _lstar_coherence_census(gates):
    """The coherence census: the r287 vdC theorem set (T1-T4,
    module-own exact Fractions), the r289 2-power resonance leg (T5)
    and the Baker need documentation (T6), plus the typed measurement
    pins (M1-M11) whose ground truth is sealed probe-side and
    re-verified by the embedded pattern gates."""

    def chk(name, ok, detail=""):
        gates.append(bool(ok))
        print("  [%s] %s%s" % ("PASS" if ok else "FAIL", name,
                               ("  -- " + detail) if detail else ""),
              flush=True)

    print("\n" + "-" * 74)
    print("MODULE-OWN EXACT SECTION S0: the L* coherence census "
          "(T1-T6 + M1-M11)")
