    # ---- T1: Fejer window-sum identity (exact at every H)
    ok = True
    for P in _SEQS:
        m = len(P)
        for H in range(1, m + 1):
            W = _window_sums(P, H)
            ok &= (len(W) == m + H - 1)
            ok &= (_fejer_windowsum(P, H)
                   == _Fr(1, H) * sum(w * w for w in W))
            ok &= (_fejer_windowsum(P, H) >= 0)
    chk("T1-vdc-window-identity", ok,
        "sum_{|h|<H} (1 - |h|/H) A(h) == (1/H) sum_t W_t^2 exact at "
        "every H on all %d frozen rational sequences (nonnegativity "
        "for free -- the Fejer smoothing is a sum of squares)"
        % len(_SEQS))

    # ---- T2: the vdC inequality, exact, with the covering identity
    # ---- and the H = 1 equality witness
    ok = True
    for P in _SEQS:
        m = len(P)
        s = sum(P)
        for H in range(1, m + 1):
            W = _window_sums(P, H)
            ok &= (sum(W) == H * s)          # H-fold covering
            ok &= (s * s <= _vdc_bound_sq(P, H))
    Peq = [_Fr(1)] * 6
    ok &= (sum(Peq) ** 2 == _vdc_bound_sq(Peq, 1))
    chk("T2-vdc-inequality-exact", ok,
        "|sum P|^2 <= ((m + H - 1)/H) x windowsum at every H on all "
        "frozen sequences (proof route gated: sum_t W_t == H sum_j "
        "P_j covering identity + Cauchy-Schwarz over m + H - 1 "
        "positions); H = 1 equality witness P = 1^6 (36 == 36) -- "
        "an EXACT, CONSTANT-FREE, ARITHMETIC-FREE finite theorem")

