    # ---------------- S6: the autocorrelation lag profile
    section("S6  AUTOCORRELATION LAG PROFILE (THE c3 MAP)")
    ac_worst = 0.0
    band_shares = {b: [] for b in LAG_BANDS}
    band_shares_exc = {b: [] for b in LAG_BANDS}
    large_small = []
    n_qual = 0
